import json,re,copy,hashlib,subprocess,collections
from pathlib import Path
W=Path.cwd();D=W/'temp/p9-formal-reconversion';R=W/'temp/GBS-ROOT-LLVM-X86/local/BUILD-ROOTS/scratch.x86_64.0'
def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
def differences(a,b,p=''):
 ds=[]
 if isinstance(a,dict) and isinstance(b,dict):
  for k in sorted(a.keys()|b.keys()):
   if k not in a or k not in b:ds.append(dict(path=p+'.'+k,before=a.get(k,'ABSENT'),after=b.get(k,'ABSENT')))
   else:ds+=differences(a[k],b[k],p+'.'+k)
 elif isinstance(a,list) and isinstance(b,list) and len(a)==len(b):
  for i,(aa,bb) in enumerate(zip(a,b)):ds+=differences(aa,bb,p+f'[{i}]')
 elif a!=b:ds.append(dict(path=p,before=a,after=b))
 return ds
def parse(p):
 roots={};stack=[]
 for line in p.read_text().splitlines():
  if not line or line.startswith('#'):continue
  n=len(line)-len(line.lstrip());s=line.strip()
  if n==0:
   name,total,head=s.rsplit(':',2);node=dict(name=name,total=int(total),head=int(head),body={},calls={});roots[name]=node;stack=[(0,node)]
  else:
   while stack[-1][0]>=n:stack.pop()
   parent=stack[-1][1];key,value=s.split(': ',1)
   if re.fullmatch(r'\d+',value):parent['body'][key]=int(value)
   else:
    name,total=value.rsplit(':',1);node=dict(name=name,total=int(total),body={},calls={})
    parent['calls'][(key,name)]=node;stack.append((n,node))
 return roots
def positions(roots):
 def rec(n):return len(n['body'])+sum(rec(c) for c in n['calls'].values())
 return sum(rec(n) for n in roots.values())
def text_profile(src,dest):
 cmd=[str(R/'lib64/ld-linux-x86-64.so.2'),'--library-path',f'{R}/lib64:{R}/usr/lib64',str(R/'usr/bin/llvm-profdata'),'merge','--sample','--text',str(src),'-o',str(dest)]
 p=subprocess.run(cmd,capture_output=True,text=True)
 dest.with_suffix('.command.json').write_text(json.dumps(dict(command=cmd,rc=p.returncode,stderr=p.stderr),indent=2))
 assert p.returncode==0,p.stderr
def compare(x,out,nonleaf,period=False):
 suffix='-period' if period else ''
 old=Path(x['output_directory']);a=json.loads((old/f'quality{suffix}.json').read_text());b=json.loads((out/f'quality{suffix}.json').read_text())
 oldprof=old/f'profile{suffix}.extbinary';newprof=out/f'profile{suffix}.extbinary'
 text_profile(oldprof,out/f'old{suffix}.text');text_profile(newprof,out/f'new{suffix}.text')
 oldtree=parse(out/f'old{suffix}.text');newtree=parse(out/f'new{suffix}.text')
 # Prior independently classified raw addresses, never new P9 classifications.
 bad={int(v['address'],16):v for v in nonleaf['addresses']}
 raw={}
 for addr,count,ps in re.findall(r'^IP-ADDRESS (0x[0-9a-f]+) sample_count=(\d+) period_sum=(\d+)',(old/'stdout').read_text(),re.M):
  raw[int(addr,16)]=(int(count),int(ps))
 lostcount=sum(raw[k][0] for k in bad);lostperiod=sum(raw[k][1] for k in bad)
 assert lostcount==nonleaf['nonleaf_samples']
 roots=collections.defaultdict(lambda:[0,0])
 for k,z in bad.items():
  roots[z['root']][0]+=raw[k][0];roots[z['root']][1]+=raw[k][1]
 unit=a['semantics']['p_ref'];weighted=lostperiod if period else lostcount
 expected=copy.deepcopy(a)
 sub=dict(sample_count=lostcount,period_sum=lostperiod,normalized_weight=dict(numerator=weighted,denominator=unit))
 for name,sgn in [('usable',-1),('in_func_no_line',1)]:
  node=expected['samples']['target'][name]
  for k in ['sample_count','period_sum']:node[k]+=sgn*sub[k]
  node['normalized_weight']['numerator']+=sgn*weighted
 expected['samples']['target']['in_func_no_line']['nonleaf_line_zero']=sub
 for key in ['target_usable_ratio','target_usable_sample_ratio','line_resolution_ratio']:
  expected['ratios'][key]['numerator']-=weighted if key in ['target_usable_ratio','line_resolution_ratio'] and period else lostcount
 expected['ratios']['target_usable_period_ratio']['numerator']-=lostperiod
 # Validate every retained profile node/body exactly. Only wrapped zero-line
 # callsites under independently recorded zero-line frame names can disappear.
 zero_names=set(nonleaf['zero_line_frame_functions'])
 removed=[]
 def prune(n,path):
  removed_total=0
  for (key,name),child in list(n['calls'].items()):
   if int(key.split('.')[0])>=60000 and n['name'] in zero_names:
    removed.append(dict(parent=path,callsite=key,inlinee=name,total=child['total']))
    removed_total+=child['total'];del n['calls'][(key,name)]
   else:
    removed_total+=prune(child,path+'/'+key+':'+name)
    if child['total']==0 and not child['body'] and not child['calls']:del n['calls'][(key,name)]
  n['total']-=removed_total
  return removed_total
 expectedtree=copy.deepcopy(oldtree)
 for name,n in expectedtree.items():prune(n,name)
 # For sample weights, no per-key rounding: exact tree after subtraction.
 if not period:assert expectedtree==newtree,'profile difference beyond removal of invalid callsites'
 else:
  # Independently remove the already catalogued nonleaf-zero sample lines,
  # then run immutable P8 as an exact reference, avoiding rounding tolerance.
  if lostcount:
   binary=a['identity']['binary']
   readelf=[str(R/'lib64/ld-linux-x86-64.so.2'),'--library-path',f'{R}/lib64:{R}/usr/lib64',str(R/'usr/bin/readelf'),'-lW',binary]
   rr=subprocess.run(readelf,capture_output=True,text=True);assert rr.returncode==0
   (out/'period-reference.readelf').write_text(rr.stdout)
   segs=[]
   for line in rr.stdout.splitlines():
    cols=line.split()
    if cols and cols[0]=='LOAD' and 'E' in cols[6:-1]:segs.append(tuple(int(cols[k],16) for k in [1,2,4]))
   paths={c['path'] for c in a['identity']['candidates']}
   filtered=out/'nonleaf-excluded.perfscript';removed_count=removed_period=0
   src=Path(next(v.split('=',1)[1] for v in x['command'] if v.startswith('--perfscript=')))
   pattern=re.compile(r'^\s*(-?\d+)/(-?\d+)\s+(\d+)\s+(\S+):\s+([0-9a-fA-F]+)\s+\((.*)\+0x([0-9a-fA-F]+)\)\s*$')
   with src.open() as fi,filtered.open('w') as fo:
    for line in fi:
     m=pattern.match(line);exclude=False
     if m and m[6] in paths:
      off=int(m[7],16);vs=[v+(off-o) for o,v,size in segs if o<=off<o+size]
      if len(vs)==1 and vs[0] in bad:exclude=True;removed_count+=1;removed_period+=int(m[3])
     if not exclude:fo.write(line)
   assert (removed_count,removed_period)==(lostcount,lostperiod)
   archive=W/'temp/profgen-patch9/prebuild-tool'
   assert sha(archive/'llvm-profgen')=='9f63c692a4239a222bfb86cd9dcab93b04a28fc32421306b597f4c799627fdc7'
   cmd=[('--output='+str(out/'reference-period.extbinary')) if v.startswith('--output=') else ('--quality-report='+str(out/'reference-period-quality.json')) if v.startswith('--quality-report=') else ('--perfscript='+str(filtered)) if v.startswith('--perfscript=') else '--ip-weight=period' if v=='--ip-weight=sample' else str(archive/'llvm-profgen') if v.endswith('/build/bin/llvm-profgen') else v for v in x['command']]+['--ip-period-unit=1000003']
   cmd[cmd.index('--library-path')+1]=f'{archive}:{R}/lib64:{R}/usr/lib64'
   with (out/'reference-period.stdout').open('w') as fo,(out/'reference-period.stderr').open('w') as fe:rr=subprocess.run(cmd,stdout=fo,stderr=fe)
   (out/'reference-period.command.json').write_text(json.dumps(dict(command=cmd,rc=rr.returncode,removed_samples=removed_count,removed_period=removed_period),indent=2))
   assert rr.returncode==0
   assert (out/'reference-period.extbinary').read_bytes()==newprof.read_bytes(),'P9 period != exact immutable P8 reference with independently identified bad samples removed'
  else:assert oldprof.read_bytes()==newprof.read_bytes()
 assert positions(oldtree)==a['samples']['written_positions']
 expected['samples']['written_positions']=positions(newtree)
 # Per-function raw coverage counters subtract the independently known
 # address contributions; sorted top50 uses normalized weight then name.
 for row in expected['coverage']['top50']:
  c,p=roots.get(row['name'],(0,0));rw=p if period else c
  row['counts']['sample_count']-=c;row['counts']['period_sum']-=p
  row['counts']['normalized_weight']['numerator']-=rw
  row['share']['numerator']-=rw
  row['share']['denominator']-=weighted
 expected['coverage']['top50'].sort(key=lambda z:(-z['counts']['normalized_weight']['numerator'],z['name']))
 expected['tool']['arguments']=[s.replace(str(oldprof),str(newprof)).replace(str(old/f'quality{suffix}.json'),str(out/f'quality{suffix}.json')) for s in a['tool']['arguments']]
 ds=differences(a,b);unexpected=differences(expected,b)
 result=dict(source=x['source'],weight='period' if period else 'sample',moved_samples=lostcount,moved_period=lostperiod,old_profile_sha256=sha(oldprof),new_profile_sha256=sha(newprof),profile_equal=oldprof.read_bytes()==newprof.read_bytes(),removed_callsites=removed,JSON_differences=ds,unexpected=unexpected,old_written_positions=positions(oldtree),new_written_positions=positions(newtree))
 (out/f'comparison{suffix}.json').write_text(json.dumps(result,indent=2)+'\n')
 assert not unexpected,unexpected[:3]
 return result
